import React, { useEffect, useState } from 'react';
import axios from 'axios';
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from 'recharts';
import { CloudRain, AlertTriangle, CheckCircle, Activity } from 'lucide-react';
import './RiverDashboard.css';

// Backend presign endpoint (updated)
const PRESIGN_ENDPOINT = 'http://127.0.0.1:8000/api/weather/s3-presign';

// Direct S3 fallback (if presign is unreachable and files are public)
const S3_BUCKET = 'aqi-training';
const S3_REGION = 'us-east-1';
const S3_PREFIX = 'aqi-training';

const RiverDashboard = () => {
  const [forecastData, setForecastData] = useState([]);
  const [analysisData, setAnalysisData] = useState(null);
  
  // 1. New State for Labels
  const [labelData, setLabelData] = useState([]);
  const [loading, setLoading] = useState(true);

  const fetchData = async (type) => {
    try {
      // Frontend will send the exact filename via `file` param
      const fileParam = type === 'forecast' ? 'forecast_outputs.csv' : (type === 'causality' ? 'lime_short_sentences.txt' : 'latest_water_level.csv');

      const response = await axios.get(PRESIGN_ENDPOINT, {
        params: { file: fileParam },
        timeout: 10000,
      });

      if (response.data && response.data.url) {
        const fileResponse = await axios.get(response.data.url, { responseType: 'text' });
        if (type === 'forecast') setForecastData(parseCSV(fileResponse.data));
        else if (type === 'causality') setAnalysisData(fileResponse.data);
        else if (type === 'labels') setLabelData(parseCSV(fileResponse.data));
        return;
      }
    } catch (err) {
      console.error(`Presign fetch failed for ${type}:`, err);
      // Try public S3 direct URL as a fallback
      try {
        const fileParam = type === 'forecast' ? 'forecast_outputs.csv' : (type === 'causality' ? 'lime_short_sentences.txt' : 'latest_water_level.csv');
        const prefix = S3_PREFIX ? `${S3_PREFIX.replace(/^\/+|\/+$/g, '')}/` : '';
        const s3Url = `https://${S3_BUCKET}.s3.${S3_REGION}.amazonaws.com/${prefix}${fileParam}`;
        console.log(`Attempting direct S3 fetch: ${s3Url}`);
        const fileResponse = await axios.get(s3Url, { responseType: 'text' });
        if (type === 'forecast') setForecastData(parseCSV(fileResponse.data));
        else if (type === 'causality') setAnalysisData(fileResponse.data);
        else if (type === 'labels') setLabelData(parseCSV(fileResponse.data));
        return;
      } catch (s3err) {
        console.error(`Direct S3 fetch failed for ${type}:`, s3err);
      }
    }
  };

  const parseCSV = (csvText) => {
    const lines = csvText.trim().split('\n');
    return lines.slice(1).map((line) => {
      const values = line.split(',');
      if (values.length < 2) return null;
      return {
        time: values[0],
        level: parseFloat(values[1]),
      };
    }).filter(item => item !== null && !isNaN(item.level));
  };

  useEffect(() => {
    // 3. Add 'labels' to the fetch list
    Promise.all([
      fetchData('forecast'), 
      fetchData('causality'),
      fetchData('labels') 
    ]).finally(() => setLoading(false));
  }, []);

  return (
    <div className="dashboard-container">
      <header className="dashboard-header">
        <h1>River Water Level Dashboard</h1>
        <div className="status-indicator online">
          <CheckCircle size={16} />
          <span>Live feed</span>
        </div>
      </header>

      <div className="main-content">
        <div className="chart-section">
          <div className="section-header">
            <Activity className="icon" />
            <h2>6-Hour Water Level Forecast</h2>
          </div>
          
          {forecastData.length > 0 ? (
            <div className="chart-container">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={forecastData}>
                  <defs>
                    <linearGradient id="colorLevel" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#0ea5e9" stopOpacity={0.8} />
                      <stop offset="95%" stopColor="#0ea5e9" stopOpacity={0} />
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" stroke="#334155" />
                  <XAxis dataKey="time" stroke="#94a3b8" />
                  <YAxis stroke="#94a3b8" domain={['auto', 'auto']} />
                  <Tooltip contentStyle={{ backgroundColor: '#1e293b', borderColor: '#334155' }} />
                  {/* Forecast Line */}
                  <Area
                    type="monotone"
                    dataKey="level"
                    stroke="#0ea5e9"
                    fillOpacity={1}
                    fill="url(#colorLevel)"
                    name="Forecast"
                  />
                  {/* Optional: You can visualize the Labels data here too if you merge the data arrays */}
                </AreaChart>
              </ResponsiveContainer>
            </div>
          ) : (
             <div className="waiting-message">
               <p>{loading ? "Loading data..." : "No data available."}</p>
             </div>
          )}
        </div>

        <div className="analysis-section">
          <div className="section-header">
            <CloudRain className="icon" />
            <h2>AI Causality Analysis</h2>
          </div>
          
          <div className="analysis-content">
            {analysisData ? (
              <ul>
                {analysisData.split('\n').map((sentence, index) => (
                  sentence.trim() && <li key={index}>{sentence}</li>
                ))}
              </ul>
            ) : (
              <p>{loading ? "Waiting for AI analysis..." : "Analysis unavailable."}</p>
            )}
          </div>
        </div>
      </div>

      <footer className="dashboard-footer">
        <AlertTriangle size={16} className="warning-icon" />
        <p>
          DISCLAIMER: This AI system provides experimental flood risk estimates.
          Always follow official alerts.
        </p>
      </footer>
    </div>
  );
};

export default RiverDashboard;
